from ortools.sat.python import cp_model
import json

def main():
    model = cp_model.CpModel()

    projects = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon', 'Zeta', 'Eta', 'Theta', 'Iota', 'Kappa']

    profit = {
        'Alpha': 12000, 'Beta': 18000, 'Gamma': 14000, 'Delta': 16000, 'Epsilon': 13000, 
        'Zeta': 20000, 'Eta': 11000, 'Theta': 17000, 'Iota': 15000, 'Kappa': 19000
    }

    cost = {
        'Alpha': 8000, 'Beta': 12000, 'Gamma': 10000, 'Delta': 15000, 'Epsilon': 11000, 
        'Zeta': 18000, 'Eta': 9000, 'Theta': 14000, 'Iota': 7000, 'Kappa': 16000
    }

    budget = 40000

    synergy_pairs = [
        ('Alpha', 'Epsilon'), ('Beta', 'Delta'), ('Delta', 'Eta'), ('Epsilon', 'Theta'), 
        ('Zeta', 'Iota'), ('Beta', 'Eta'), ('Delta', 'Theta'), ('Gamma', 'Iota'), 
        ('Epsilon', 'Kappa'), ('Theta', 'Iota'), ('Iota', 'Kappa'), ('Delta', 'Kappa'), 
        ('Epsilon', 'Iota'), ('Theta', 'Kappa')
    ]

    synergy_bonus = {
        ('Alpha', 'Epsilon'): 4000, ('Beta', 'Delta'): 6000, ('Delta', 'Eta'): 9000, 
        ('Epsilon', 'Theta'): 7000, ('Zeta', 'Iota'): 9000, ('Beta', 'Eta'): 7000, 
        ('Delta', 'Theta'): 5000, ('Gamma', 'Iota'): 6000, ('Epsilon', 'Kappa'): 8000, 
        ('Theta', 'Iota'): 8000, ('Iota', 'Kappa'): 7000, ('Delta', 'Kappa'): 4000, 
        ('Epsilon', 'Iota'): 5000, ('Theta', 'Kappa'): 6000
    }

    incompatible_pairs = [
        ('Alpha', 'Delta'), ('Beta', 'Theta'), ('Gamma', 'Zeta'), 
        ('Epsilon', 'Iota'), ('Eta', 'Kappa')
    ]

    select = {}
    for p in projects:
        select[p] = model.NewBoolVar(f"select_{p}")

    synergy_active = {}
    for p, q in synergy_pairs:
        synergy_active[(p, q)] = model.NewBoolVar(f"synergy_{p}_{q}")

    total_cost = sum(cost[p] * select[p] for p in projects)
    model.Add(total_cost <= budget)

    for p, q in incompatible_pairs:
        model.Add(select[p] + select[q] <= 1)

    for p, q in synergy_pairs:
        model.Add(synergy_active[(p, q)] <= select[p])
        model.Add(synergy_active[(p, q)] <= select[q])
        model.Add(synergy_active[(p, q)] >= select[p] + select[q] - 1)

    total_profit = sum(profit[p] * select[p] for p in projects)
    total_synergy = sum(synergy_bonus[(p, q)] * synergy_active[(p, q)] for p, q in synergy_pairs)

    model.Maximize(total_profit + total_synergy)

    solver = cp_model.CpSolver()

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        selected_projects = [int(solver.Value(select[p])) for p in projects]
        total_profit_value = int(solver.ObjectiveValue())
        total_cost_value = sum(cost[p] * solver.Value(select[p]) for p in projects)
    else:
        selected_projects = []
        total_profit_value = 0
        total_cost_value = 0

    print(json.dumps({
        "selected_projects": selected_projects,
        "total_profit": total_profit_value,
        "total_cost": total_cost_value
    }))

if __name__ == '__main__':
    main()
